import{_ as r,a as n}from"./chunks/99525999f545b8766774.oaLPhSr6.js";import{_ as o,C as s,o as p,c as i,j as t,a as l,E as m,a5 as h}from"./chunks/framework.DNkHA0lr.js";const v=JSON.parse('{"title":"如果你想在2022年蓬勃发展，请学习这些技能","description":"","frontmatter":{"title":"如果你想在2022年蓬勃发展，请学习这些技能","originalTitle":"Learn These Skills If You Want To Thrive In 2022","date":"2022-02-25","originalUrl":"https://thedankoe.com/letters/learn-these-skills-if-you-want-to-thrive-in-2022/","minutes":7,"sourceHash":"799fa1ffd2480301f27cbcfeab617fa333e97c5ff495832ddd062ec408ba84c4","translation":"AI-assisted, block-aligned; not official","head":[["link",{"rel":"canonical","href":"https://thedankoe.com/letters/learn-these-skills-if-you-want-to-thrive-in-2022/"}]]},"headers":[],"relativePath":"letters/learn-these-skills-if-you-want-to-thrive-in-2022.md","filePath":"letters/learn-these-skills-if-you-want-to-thrive-in-2022.md"}'),c={name:"letters/learn-these-skills-if-you-want-to-thrive-in-2022.md"};function d(u,e,f,g,_,k){const a=s("ArticleMeta");return p(),i("div",null,[e[0]||(e[0]=t("h1",{id:"如果你想在2022年蓬勃发展-请学习这些技能",tabindex:"-1"},[l("如果你想在2022年蓬勃发展，请学习这些技能 "),t("a",{class:"header-anchor",href:"#如果你想在2022年蓬勃发展-请学习这些技能","aria-label":'Permalink to "如果你想在2022年蓬勃发展，请学习这些技能"'},"​")],-1)),m(a),e[1]||(e[1]=h('<p><em>“Dan，最值得学习的技能是什么？”</em></p><p><em>“Dan，我该如何在网上赚钱？”</em></p><p><em>“Dan，我怎么才能完全不工作、不研究、不执行，就在不到3周内建立被动收入？”</em></p><p><strong>停下</strong>。你问错问题了。你<em>需要</em>学习的技能只有少数几个。你学习的其他技能应该是你天生好奇心的结果。用你的时间冒点小险，去换取潜在的巨大回报。让（好的）新奇事物成为你的向导（正如上一期精通指南 Mastery Letter 所说）。</p><p>让我用最简单的方式为你拆解你应该学什么。如果你遵循这条学习路径，你将永远不必再为钱发愁——前提是你至少能在这条路上坚持1年。</p><h2 id="变得有价值" tabindex="-1">变得有价值 <a class="header-anchor" href="#变得有价值" aria-label="Permalink to &quot;变得有价值&quot;">​</a></h2><p>在物质世界中，别人对你的感知价值与你解决问题的<em>数量</em>相关。从个人意义上讲——在永恒市场（健康、财富和人际关系）中提升自己，会让你成为一个“高价值”个体。人们会被你吸引，因为你填补了他们生活中的空缺。你解决了一个问题。</p><p>在商业世界中，这些“提升”转化为为他人解决生物学问题的能力——因为你已经为自己解决过这些问题了。问题在于，你需要懂得如何打包和传达这种价值。你需要吸引人们。粉丝。潜在客户。顾客。</p><p>提升自己只是拼图的一角。它比任何事物都更关乎一种教育业务。教练辅导、培训项目、数字产品等等。这些是次要的，但对于设定场景是必要的。要将这些技能变现需要时间——因为为你自己解决这些问题就需要时间。</p><p>在你提升自己的同时，以下是你应该掌握的技能：</p><h3 id="常青技能" tabindex="-1"><strong>常青技能</strong> <a class="header-anchor" href="#常青技能" aria-label="Permalink to &quot;**常青技能**&quot;">​</a></h3><p>有大量的技能被创作者（content creators）吹得天花乱坠。他们冲你大喊去学这些，这样你就能赚到某种网络收入。我想回到根本。那些能产生最大影响并让你快速将任何想要的东西变现的技能。</p><p>常青技能中有两大类将<em>始终</em>具有价值。它们让你能够在公开市场中创造和展示你的产品或服务。</p><p><img src="'+r+'" alt=""></p><p>常青技能树</p><p>第一类我称之为<strong>媒介</strong>。媒介有两种。写作和演讲。写作是得体、清晰演讲的基础，应当首先被理解。写作——书面文字——是你在现代世界中组织和传达思想的方式。与其他人类的沟通——在其根本形态上——就是写作。</p><p>网上有大量学习写作的资源。我会在未来的通讯中教你如何学习，但我不能也不会给你循序渐进的建议。那会毁了整个旅程的意义。正如你将学到的那样，如果我给你确切的步骤——那将毫无成就感。你会放弃得和开始时一样快。你需要让好奇心驱使你。通过自我教育和一头扎进未知领域，让势头的雪球越滚越大。一旦你学会了走，你就能跑。一旦你学会了写，你就能说。</p><p>第二类常青技能是<strong>信息</strong>。营销和销售。你如何通过写作和演讲来捕获注意力——他人的关注点——从而推销你的解决方案。这些是理解广告、心理学、人性、捕捉注意力以及什么在驱动我们做出决策的总称。如果不理解这些，你就无法有效地写作或演讲。你可以通过自我认知和观察他人学到很多关于这些技能的知识。注意他们关注什么以及为什么关注。</p><p>这就是你如何让人们开始接受你的价值。这就是你如何引发行为改变。行为改变是唯一重要的指标。为什么？这意味着他们会在生活中看到积极的结果。这就是你为你的努力获得报酬的方式。没有营销和销售，你就不会有收入。</p><p>对某些人来说，这些词带有负面含义，因为你曾在这些方面有过糟糕的经历。你对带有负面能量的信息的负面关注，产生了负面的反应。请摆脱这种观念，看清这些技能的本质——一种传播你的积极信息并解决他人深层问题的方法。如果你不去营销和销售你的解决方案，你一辈子都在为别人营销和销售他们的解决方案。</p><p>写作、演讲、营销和销售这4个技能，将为你开启利润丰厚的在线职业生涯奠定基础。如果你出于自己的好奇心去追求这些，却<em>没</em>能找到一条可走的路……那我都不知道该怎么说了。</p><p><strong>通讯中插播无耻硬广</strong>：营销和销售是 <a href="https://join.modernmastery.co/?utm_campaign=The%20Mastery%20Letter&amp;utm_medium=email&amp;utm_source=Revue%20newsletter" target="_blank" rel="noreferrer">Modern Mastery HQ.</a> 商业端的核心教学内容。成百上千的资源、课程、路线图以及个性化支持，助你找到赚钱的道路。</p><p><strong>补充技能</strong></p><p>补充技能能让你进一步扩大常青技能的影响力。摄影、摄像、网页和平面设计、技术熟练度、音频工程、企业管理等等。</p><p>逐一理解这些技能将放大你常青技能的效果，反之亦然。它们是<em>能让你展示、可视化和扩展常青技能影响力的创意、技术和商业技能。</em></p><p>大多数人最先学习的正是这些。缺点是：他们从未学会建立在线杠杆（leverage），也没学会在网上以高价出售他们的产品和服务。他们掉进了“挨饿的艺术家”陷阱。请不惜一切代价避免这种情况，把获取常青技能放在首位。</p><p>你的常青技能可用于营销、销售并将你的补充技能变现。所有这些技能都可以用来展示你的价值，这些价值与你的兴趣以及你为自己解决过的问题有关。在你的自我教育旅途中跋涉时，这些技能自然会显露出来。不同的项目需要不同的补充技能。</p><p>作为一家一人企业（one-person business），你甚至必须学习其中很多技能才能生存。你们大多数人都知道我的故事（以及许多其他成功的单人创业者的故事）。我尝试过利用多种不同的补充技能做自由职业。创办过一个数字艺术主页。做过好几个电商品牌。等等。当<a href="https://join.modernmastery.co/?utm_campaign=The%20Mastery%20Letter&amp;utm_medium=email&amp;utm_source=Revue%20newsletter" target="_blank" rel="noreferrer">我开始建立受众群体，学习了营销和销售，并把精力集中在能带来收入的事情上</a>时，一切都改变了。</p><p><strong>关于饱和的说明</strong></p><p>大多数永恒市场<em>确实</em>饱和了。竞争者很多。其中大多数都是新手。他们中的绝大多数甚至都还没达到“有价值”的阶段。很少有人在常青技能方面高于平均水平。</p><p>我不想让你在我们将深入探讨不可替代性时感到气馁。那是一场关于时间的游戏。它需要时间。要知道，凭借好奇心、常青技能以及几项补充技能，你可以赚到一笔非常可观的钱。它们都会相互渗透。它们是相互关联的。</p><h2 id="变得不可替代" tabindex="-1"><strong>变得不可替代</strong> <a class="header-anchor" href="#变得不可替代" aria-label="Permalink to &quot;**变得不可替代**&quot;">​</a></h2><p>要赚取体面的生活费（而不是仅供<em>生存</em>的工资），你必须变得有价值。要创造无限的收入，你必须变得不可替代。在当今世界，变得有价值就等同于成为一件商品。每个人都能凭自己掌握的技能提供某种形式的价值。很少有人能针对独特的局面，提供一套不可替代的、具体适用的技能和知识组合并取得成果。</p><p>通过你设计的系统来确保解决问题的能力。正如我们所讨论的，技能获取是必要的，但特定知识能让你最大化地利用这些技能。你能够填补别人无法填补的空缺。<strong>如果你想变得有价值，就要了解规则。如果你想变得不可替代，就要知道何时打破规则。</strong></p><p><img src="'+n+'" alt=""></p><p>技能矩阵</p><p>这就是永恒市场、学习、解决自身问题以及经验发挥作用的地方。变得不可替代与其说关乎你解决了什么问题，不如说更关乎你如何解决它。在接下来的几周里，我将写一封关于“解决方案经济（The Solutions Economy）”和“经验模型（The Experience Model）”的通讯——但现在，你要明白，你通过技能组合<em>应用知识</em>的能力才是关键。</p><p>大玩家之所以不可替代，是因为他们经验丰富。他们解决了自己的问题 &gt; 获得经验 &gt; 创办了一项服务业务（咨询、教练辅导、自由职业） &gt; 获得经验 + 开始开发自己能取得成果的独特系统 &gt; 加上一点坚持和迭代 &gt; 将他们的系统产品化 &gt; 重复这个循环。</p><p>进一步来说：通往不可替代性的道路涉及保持开放的心态（能够转型和学习），研究你主打产品的所有周边领域，调查方方面面，不要对某一种做事方式教条主义，等等。如果你把自己关在一个盒子里，你的收入也会被关在盒子里。被封顶。</p><p><em>样样涉猎，精通一门。</em></p><p>与其把所有的精力都集中在增加收入上——你必须专注于<em>在</em>减少时间投入的同时增加收入。不断地迭代、系统化、产品化，不要因为你的服务业务达到了每月2万美元就停滞不前。尤其是当你可以在工作更少的情况下达到每月100万美元时。</p><p>很多人还没有达到这个水平。我不想让你感到困惑或不知所措。从常青技能和补充技能开始。开始通过积累受众来建立杠杆（leverage）。开展一项服务业务，提供免费帮助，并开发你的系统。之后，道路自然会展现在你面前。</p><p>一如既往，如果你想要循序渐进的流程、策略，以及在其他地方都被下架的我的3门初学者课程（开展服务业务、积累受众和打造数字房地产），<a href="https://join.modernmastery.co/?utm_campaign=The%20Mastery%20Letter&amp;utm_medium=email&amp;utm_source=Revue%20newsletter" target="_blank" rel="noreferrer">请加入 MMHQ</a>。</p><p><em>Dan Koe</em></p><hr><p><a href="/en/letters/learn-these-skills-if-you-want-to-thrive-in-2022">查看英文存档</a> · <a href="/letters/">返回全部文章</a></p>',46))])}const y=o(c,[["render",d]]);export{v as __pageData,y as default};
